implements(Key) :-
    citation(Key, _).

citation(ch_fadp_art_5_h, [label - 'Bundesgesetz über den Datenschutz (DSG), SR 235.1, Art 5 Bst. h, definition of Verletzung der Datensicherheit (breach of data security)', ref - 'https://www.fedlex.admin.ch/eli/cc/2022/491/de#art_5 (unit ch-fadp-sr-235-1-2025-07-07#art_5/para/lbl_h)', verbatim - 'Verletzung der Datensicherheit: eine Verletzung der Sicherheit, die dazu führt, dass Personendaten unbeabsichtigt oder widerrechtlich verlorengehen, gelöscht, vernichtet oder verändert werden oder Unbefugten offengelegt oder zugänglich gemacht werden']).
citation(ch_fadp_art_24_1, [label - 'Bundesgesetz über den Datenschutz (DSG), SR 235.1, Art 24 Abs. 1, report of the controller to the EDÖB (likely high risk threshold)', ref - 'https://www.fedlex.admin.ch/eli/cc/2022/491/de#art_24 (unit ch-fadp-sr-235-1-2025-07-07#art_24/para_1)', verbatim - 'Der Verantwortliche meldet dem EDÖB so rasch als möglich eine Verletzung der Datensicherheit, die voraussichtlich zu einem hohen Risiko für die Persönlichkeit oder die Grundrechte der betroffenen Person führt.']).
citation(ch_fadp_art_24_3, [label - 'Bundesgesetz über den Datenschutz (DSG), SR 235.1, Art 24 Abs. 3, report of the processor to the controller', ref - 'https://www.fedlex.admin.ch/eli/cc/2022/491/de#art_24 (unit ch-fadp-sr-235-1-2025-07-07#art_24/para_3)', verbatim - 'Der Auftragsbearbeiter meldet dem Verantwortlichen so rasch als möglich eine Verletzung der Datensicherheit.']).
citation(ch_fadp_art_24_4, [label - 'Bundesgesetz über den Datenschutz (DSG), SR 235.1, Art 24 Abs. 4, information of the data subject (necessary for protection or requested by the EDÖB)', ref - 'https://www.fedlex.admin.ch/eli/cc/2022/491/de#art_24 (unit ch-fadp-sr-235-1-2025-07-07#art_24/para_4)', verbatim - 'Der Verantwortliche informiert die betroffene Person, wenn es zu ihrem Schutz erforderlich ist oder der EDÖB es verlangt.']).
citation(ch_fadp_art_24_5, [label - 'Bundesgesetz über den Datenschutz (DSG), SR 235.1, Art 24 Abs. 5 lead-in, permission to restrict, defer or dispense with the information of the data subject', ref - 'https://www.fedlex.admin.ch/eli/cc/2022/491/de#art_24 (units ch-fadp-sr-235-1-2025-07-07#art_24/para_5, #art_24/para_5/listintro)', verbatim - 'Er kann die Information an die betroffene Person einschränken, aufschieben oder darauf verzichten, wenn:']).
citation(ch_fadp_art_24_5_a, [label - 'Bundesgesetz über den Datenschutz (DSG), SR 235.1, Art 24 Abs. 5 Bst. a, ground under Art 26 Abs. 1 Bst. b or Abs. 2 Bst. b, or statutory duty of secrecy', ref - 'https://www.fedlex.admin.ch/eli/cc/2022/491/de#art_24 (unit ch-fadp-sr-235-1-2025-07-07#art_24/para_5/lbl_a)', verbatim - 'eine gesetzliche Geheimhaltungspflicht dies verbietet']).
citation(ch_fadp_art_24_5_b, [label - 'Bundesgesetz über den Datenschutz (DSG), SR 235.1, Art 24 Abs. 5 Bst. b, information impossible or requiring disproportionate effort', ref - 'https://www.fedlex.admin.ch/eli/cc/2022/491/de#art_24 (unit ch-fadp-sr-235-1-2025-07-07#art_24/para_5/lbl_b)', verbatim - 'die Information unmöglich ist oder einen unverhältnismässigen Aufwand erfordert']).
citation(ch_fadp_art_24_5_c, [label - 'Bundesgesetz über den Datenschutz (DSG), SR 235.1, Art 24 Abs. 5 Bst. c, information ensured comparably by a public announcement', ref - 'https://www.fedlex.admin.ch/eli/cc/2022/491/de#art_24 (unit ch-fadp-sr-235-1-2025-07-07#art_24/para_5/lbl_c)', verbatim - 'die Information der betroffenen Person durch eine öffentliche Bekanntmachung in vergleichbarer Weise sichergestellt ist']).
citation(eu_reg_2016_679_art_33_1, [label - 'Regulation (EU) 2016/679 (GDPR) Art 33(1), notification of a personal data breach to the supervisory authority', ref - 'https://eur-lex.europa.eu/eli/reg/2016/679/oj (consolidation 02016R0679-20160504, unit parag_033.001)', verbatim - 'unless the personal data breach is unlikely to result in a risk to the rights and freedoms of natural persons']).
